/**
 * Typed access to the generated schedule and the rules that turn it into a day
 * view: segment order, which segment runs now, and how much of the day is done.
 *
 * `data/schedule.json` is generated by `npm run data` from `data/schedule.csv`,
 * so this module only reads it.
 */

import scheduleDocument from '../data/schedule.json';

/** Week day keys, in the order the week is displayed. */
export const DAY_KEYS = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'] as const;

export type DayKey = (typeof DAY_KEYS)[number];

/** What a segment is. Only `tracked` segments count toward the day progress. */
export type EntryKind = 'routine' | 'study' | 'sport' | 'break' | 'rest' | 'sleep';

/** One segment of the schedule. */
export type ScheduleEntry = {
  id: string;
  start: string;
  end: string;
  kind: EntryKind;
  /** Icon name looked up in the icon registry, for example `Dumbbell`. */
  icon: string;
  title: string;
  note: string;
  tracked: boolean;
};

/** One day of the week with its segments in time order. */
export type ScheduleDay = {
  key: DayKey;
  label: string;
  fullLabel: string;
  entries: ScheduleEntry[];
};

/** Where a segment sits relative to the current time. */
export type EntryPhase = 'past' | 'current' | 'future';

/** Segments of one day, split by the current time. */
export type DayPhases = {
  past: ScheduleEntry[];
  current: ScheduleEntry[];
  future: ScheduleEntry[];
};

const WEEKDAY_NAMES = [
  'воскресенье',
  'понедельник',
  'вторник',
  'среда',
  'четверг',
  'пятница',
  'суббота',
];

const MONTH_NAMES = [
  'января',
  'февраля',
  'марта',
  'апреля',
  'мая',
  'июня',
  'июля',
  'августа',
  'сентября',
  'октября',
  'ноября',
  'декабря',
];

// The build script validates the generated document, so its shape is trusted
// here and only the JSON types are narrowed to the types above.
const scheduleDays = scheduleDocument.days as unknown as ScheduleDay[];

/**
 * Read one day of the schedule.
 *
 * @param key Week day key.
 * @returns The day with its segments.
 * @throws Error when the generated data has no such day.
 */
export function getScheduleDay(key: DayKey): ScheduleDay {
  const found = scheduleDays.find((day) => day.key === key);
  if (!found) {
    throw new Error(`schedule data has no day "${key}"`);
  }
  return found;
}

/**
 * Every day of the week in display order.
 *
 * @returns The week.
 */
export function getScheduleWeek(): ScheduleDay[] {
  return scheduleDays;
}

/**
 * Week day key of a date, with Monday as the first day.
 *
 * @param date Any date.
 * @returns The matching key.
 */
export function dayKeyForDate(date: Date): DayKey {
  return DAY_KEYS[(date.getDay() + 6) % 7];
}

/**
 * Convert `HH:MM` to minutes from midnight so times can be compared as numbers.
 *
 * @param time Time of day.
 * @returns Minutes from midnight.
 */
export function timeToMinutes(time: string): number {
  const [hours, minutes] = time.split(':').map(Number);
  return hours * 60 + minutes;
}

/**
 * Minutes from midnight for a moment, used to compare against segment times.
 *
 * @param date Any moment.
 * @returns Minutes from midnight in local time.
 */
export function minutesOfDate(date: Date): number {
  return date.getHours() * 60 + date.getMinutes();
}

/**
 * Where a segment sits relative to `nowMinutes`.
 *
 * @param entry Schedule segment.
 * @param nowMinutes Minutes from midnight, or null when the shown day is not
 *   today and nothing should be marked as running.
 * @returns `past` for finished segments, `current` for the running one, and
 *   `future` otherwise.
 */
export function entryPhase(entry: ScheduleEntry, nowMinutes: number | null): EntryPhase {
  if (nowMinutes === null) {
    return 'future';
  }
  if (timeToMinutes(entry.end) <= nowMinutes) {
    return 'past';
  }
  if (timeToMinutes(entry.start) <= nowMinutes) {
    return 'current';
  }
  return 'future';
}

/**
 * Split a day into the segments that already finished, the one running now and
 * the rest.
 *
 * @param entries Segments of one day.
 * @param nowMinutes Minutes from midnight, or null for a day that is not today.
 * @returns Segments grouped by phase, each group in time order.
 */
export function splitDayPhases(entries: ScheduleEntry[], nowMinutes: number | null): DayPhases {
  const phases: DayPhases = {past: [], current: [], future: []};
  for (const entry of entries) {
    phases[entryPhase(entry, nowMinutes)].push(entry);
  }
  return phases;
}

/**
 * Count how much of a day is done.
 *
 * @param entries Segments of one day.
 * @param doneIds Identifiers marked as done.
 * @returns Done and total counts of the segments that carry a checkbox.
 */
export function countProgress(
  entries: ScheduleEntry[],
  doneIds: ReadonlySet<string>,
): {done: number; total: number} {
  const tracked = entries.filter((entry) => entry.tracked);
  const done = tracked.filter((entry) => doneIds.has(entry.id)).length;
  return {done, total: tracked.length};
}

/**
 * Stable identifier of a calendar day, used as the key marks are stored under.
 * Built from local date parts, so a day never shifts because of the UTC offset.
 *
 * @param date Any date.
 * @returns `YYYY-MM-DD`.
 */
export function dateKey(date: Date): string {
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${date.getFullYear()}-${month}-${day}`;
}

/**
 * Monday of the week that contains a date.
 *
 * @param date Any date.
 * @returns A new date at local midnight of that Monday.
 */
export function startOfWeek(date: Date): Date {
  const monday = new Date(date.getFullYear(), date.getMonth(), date.getDate());
  monday.setDate(monday.getDate() - ((monday.getDay() + 6) % 7));
  return monday;
}

/**
 * Add whole days to a date.
 *
 * @param date Any date.
 * @param days Number of days, negative to go back.
 * @returns A new date.
 */
export function addDays(date: Date, days: number): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + days);
}

/**
 * Whether two dates fall on the same calendar day.
 *
 * @param left First date.
 * @param right Second date.
 * @returns True when both are the same local day.
 */
export function isSameDate(left: Date, right: Date): boolean {
  return dateKey(left) === dateKey(right);
}

/**
 * How long a segment stays open for marking after it ends, in minutes.
 * Past this window the segment is closed: it can no longer be marked as done.
 */
export const MARKING_GRACE_MINUTES = 60;

/** Milliseconds in one minute, for turning the window above into a moment. */
const MILLISECONDS_PER_MINUTE = 60_000;

/**
 * Whether a segment can still be marked as done.
 *
 * The window closes one hour after the segment ends, measured on the day that is
 * being shown, so a segment of a future day is open, a segment of a past day is
 * closed, and today closes segment by segment as the day goes on.
 *
 * @param date The day being shown.
 * @param entry Schedule segment.
 * @param now The current moment.
 * @returns True while the segment may still be marked or unmarked.
 */
export function isMarkingOpen(date: Date, entry: ScheduleEntry, now: Date): boolean {
  const endMinutes = timeToMinutes(entry.end);
  const endMoment = new Date(
    date.getFullYear(),
    date.getMonth(),
    date.getDate(),
    Math.floor(endMinutes / 60),
    endMinutes % 60,
  );
  const closesAt = endMoment.getTime() + MARKING_GRACE_MINUTES * MILLISECONDS_PER_MINUTE;
  return now.getTime() <= closesAt;
}

/**
 * Russian title of a day, for example `вторник, 14 октября`.
 *
 * @param date Any date.
 * @returns Title text.
 */
export function formatDayTitle(date: Date): string {
  return `${WEEKDAY_NAMES[date.getDay()]}, ${date.getDate()} ${MONTH_NAMES[date.getMonth()]}`;
}

/**
 * Time range of a segment, for example `09:00–10:30`.
 *
 * @param entry Schedule segment.
 * @returns Range text.
 */
export function formatTimeRange(entry: ScheduleEntry): string {
  return `${entry.start}–${entry.end}`;
}
